<script lang="ts">
 import { onMount } from 'svelte';
 import Transport from './Transport.svelte';
 import { Client, can } from './client.ts';
 type Job = { id:string;due_at:number;payload:{quantity?:number;transport?:{quantity?:number}};status:string;attempts:number;boundary_input?:{boundary:string} };
 type Status = { identity:{username:string;role:string;scopes:string[]}; application:string; quantum:number; simulation_time:string; effects:number; pending_boundary_outputs:number; providers:Record<string,string>; run:{id:string;epoch:string;state:string;mode:string;granted:number;requested:number;committed:number;speed:number;error?:string;scenario:{time_zone:string;seed:number;business_open:string;business_close:string}};jobs:Job[];heartbeats:{role:string;healthy:boolean;detail:string}[] };
 let username=$state('');let password=$state('');let client:Client|undefined=$state();let status:Status|undefined=$state();let error=$state('');let busy=$state(false);let due=$state(1);let quantity=$state(1);let speed=$state(1);let audits:Record<string,unknown>[]=$state([]);let confirmRun=$state('');let retry:ReturnType<Client['job']>|undefined=$state();let jobSaved=$state('');
 const controls=$derived(status ? can(status.identity,'runs:control') : false);
 async function refresh(){if(!client)return;try{status=await client.request<Status>('/api/status');if(can(status.identity,'audit:read'))audits=await client.request<Record<string,unknown>[]>('/api/audit');}catch(e){error=e instanceof Error?e.message:String(e)}}
 async function login(event:SubmitEvent){event.preventDefault();busy=true;error='';const c=new Client(username,password);try{status=await c.request<Status>('/api/status');client=c;password='';due=Math.max(status.run.granted,status.run.requested)+status.quantum;await refresh();}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 async function schedule(event:SubmitEvent){event.preventDefault();if(!client)return;busy=true;error='';jobSaved='';retry??=client.job(due,quantity);try{await retry.send();retry=undefined;jobSaved='Job accepted';await refresh()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 async function control(action:string){if(!client||!status)return;busy=true;error='';try{await client.request(`/api/control/${action}`,{method:'POST',body:JSON.stringify(action==='reset'?{confirm_run_id:confirmRun}:action==='speed'?{speed}: {})});confirmRun='';await refresh()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 function logout(){client=undefined;status=undefined;audits=[];retry=undefined;error=''}
 onMount(()=>{const timer=setInterval(refresh,1500);return()=>clearInterval(timer)});
</script>
<svelte:head><title>Logistics simulator</title></svelte:head>
<header><div><p class="eyebrow">Logistics</p><h1>Transport & fleet</h1></div>{#if status}<div class="identity"><span>{status.identity.username} / {status.identity.role}</span><button onclick={logout}>Log out</button></div>{/if}</header>
<main>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}
 {#if !status}
 <section class="login"><h2>Log in</h2><p>Use an identity configured for this Logistics deployment.</p><form onsubmit={login}><label>Username<input autocomplete="username" bind:value={username} required /></label><label>Password<input type="password" autocomplete="current-password" bind:value={password} required /></label><button class="primary" disabled={busy}>{busy?'Logging in…':'Log in'}</button></form></section>
 {:else}
 <section class="run-bar"><div><span class="label">Run state</span><strong class="signal">{status.run.state}</strong></div><div><span class="label">Granted time</span><strong>{status.run.granted.toFixed(1)} s</strong></div><div><span class="label">Committed time</span><strong>{status.run.committed.toFixed(1)} s</strong></div><div><span class="label">Pending outputs</span><strong>{status.pending_boundary_outputs}</strong></div></section>
 {#if client}<Transport {client} {status} />{/if}
 <details><summary>Platform diagnostics</summary>
 <div class="columns"><section><div class="section-title"><h2>Clock & providers</h2><span>{status.run.mode}</span></div><dl><dt>Simulation time</dt><dd>{status.simulation_time}</dd><dt>Requested / committed</dt><dd>{status.run.requested} / {status.run.committed} s</dd><dt>Time zone</dt><dd>{status.run.scenario.time_zone}</dd><dt>Business hours</dt><dd>{status.run.scenario.business_open}–{status.run.scenario.business_close}</dd><dt>Scenario seed</dt><dd>{status.run.scenario.seed}</dd>{#each Object.entries(status.providers) as [boundary,provider]}<dt>{boundary}</dt><dd>{provider}</dd>{/each}</dl><div class="heartbeats">{#each status.heartbeats as heartbeat}<span class:healthy={heartbeat.healthy}>{heartbeat.role}: {heartbeat.healthy?'healthy':'unavailable'}</span>{/each}</div>{#if status.run.error}<p class="error">{status.run.error}</p>{/if}<p class="identifier">Run {status.run.id}<br>Epoch {status.run.epoch}</p></section>
 {#if can(status.identity,'jobs:write')}<section><h2>Schedule sample job</h2><p>Due time must be at least {status.quantum} s beyond the granted and requested times.</p><form onsubmit={schedule}><label>Due time (simulation seconds)<input type="number" min="0" step="any" bind:value={due} disabled={!!retry} required /></label><label>Quantity (item)<input type="number" min="1" max="10000" step="1" bind:value={quantity} disabled={!!retry} required /></label><div class="actions"><button class="primary" disabled={busy}>{retry?'Retry same command':'Schedule job'}</button>{#if retry}<button type="button" onclick={()=>{retry=undefined;error=''}}>New command</button>{/if}</div>{#if jobSaved}<p role="status">{jobSaved}</p>{/if}</form></section>{/if}</div>
 </details>
 {#if controls}<section><div class="section-title"><h2>Operator controls</h2><span>Local run control</span></div><div class="actions"><button onclick={()=>control('hold')} disabled={busy}>Hold</button><button onclick={()=>control('resume')} disabled={busy}>Resume</button><button onclick={()=>control('finalize')} disabled={busy}>Finalize</button>{#if status.run.mode==='standalone'}<label class="inline">Speed<select bind:value={speed}><option value={1}>1×</option><option value={5}>5×</option><option value={20}>20×</option><option value={60}>60×</option></select></label><button onclick={()=>control('speed')} disabled={busy}>Set speed</button>{/if}</div>{#if status.run.mode==='standalone'}<details><summary>Reset run</summary><p>Creates a new run and epoch. Existing run data is retained.</p><label>Current run ID<input bind:value={confirmRun} placeholder={status.run.id} /></label><button onclick={()=>control('reset')} disabled={busy||confirmRun!==status.run.id}>Reset confirmed run</button></details>{/if}</section>{/if}
 <section><div class="section-title"><h2>Jobs</h2><span>Latest {status.jobs.length}</span></div><div class="table-wrap"><table><thead><tr><th>Job ID</th><th>Due (s)</th><th>Quantity</th><th>Status</th><th>Attempts</th><th>Provider boundary</th></tr></thead><tbody>{#each status.jobs as job}<tr><td class="identifier">{job.id}</td><td>{job.due_at}</td><td>{job.payload.quantity??job.payload.transport?.quantity??'—'} item</td><td>{job.status}</td><td>{job.attempts}</td><td>{job.boundary_input?.boundary??'Employee / boundary command'}</td></tr>{:else}<tr><td colspan="6">No jobs scheduled in this run.</td></tr>{/each}</tbody></table></div></section>
 {#if can(status.identity,'audit:read')}<section><div class="section-title"><h2>Command audit</h2><span>Latest {audits.length}</span></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Outcome</th><th>HTTP</th></tr></thead><tbody>{#each audits as audit}<tr><td>{audit.recorded_at}</td><td>{audit.actor} / {audit.role}</td><td>{audit.action}</td><td>{audit.outcome}</td><td>{audit.status_code}</td></tr>{:else}<tr><td colspan="5">No commands recorded.</td></tr>{/each}</tbody></table></div></section>{/if}
 {/if}
</main>
<footer>Logistics · Fleet and goods in transit</footer>
